// Generates a clearly synthetic album-name mapping registry for offline tests.
// It is derived only from the tracked public references, claims no human review, and is
// written to a temp directory so it can never be mistaken for the owner's reviewed registry.
const fs = require('node:fs'); const os = require('node:os'); const path = require('node:path');
const { hash } = require('../../../lib/listeningStudy/core');

function buildSyntheticMappings(references = require('../../../data/listening-study/references.json')) {
  const ref = references['born-to-die:standard'];
  const alias = (position, fromTitle) => ({ artist: ref.tracks[position - 1].artist, fromTitle, referencePosition: position,
    releaseTrackMbid: ref.tracks[position - 1].releaseTrackMbid, rationale: 'Synthetic test alias: plain title of a core track whose reference title has a remastered suffix.' });
  return {
    synthetic: true,
    scope: 'SYNTHETIC TEST REGISTRY generated from tracked references. Not human-reviewed; not for reports.',
    mappings: [{ targetStudyEditionId: 'born-to-die:standard', artist: ref.artist,
      names: ['Born to Die', 'Born to Die (Deluxe Version)', 'Born to Die (Bonus Track Version)'],
      reviewer: 'synthetic-test-fixture (no human review)', reviewedAt: 'not-reviewed-synthetic',
      sources: ['generated by tests/fixtures/listeningStudy/syntheticMappings.js from data/listening-study/references.json'],
      referenceHash: hash(ref), standardTracklistHash: hash(ref.tracks),
      trackAliases: [alias(3, 'Blue Jeans'), alias(4, 'Video Games')] }]
  };
}
function writeSyntheticMappings() {
  const dir = fs.mkdtempSync(path.join(os.tmpdir(), 'synthetic-mappings-'));
  const file = path.join(dir, 'album-name-mappings.json');
  fs.writeFileSync(file, JSON.stringify(buildSyntheticMappings()));
  process.once('exit', () => fs.rmSync(dir, { recursive: true, force: true }));
  return file;
}
module.exports = { buildSyntheticMappings, writeSyntheticMappings };
